//@ rules: BORROW-3, SCOPE-3
// One accepted twin per shape/route: copy the data before either owned position.
use std::task::Tasks;
pub struct Parts<'a> { pub first: &'a str, pub other: &'static str }
pub fn whole_direct(tasks: &Tasks) -> Box<dyn Fn() -> usize> { let text = String::from("x"); let value = text.as_str(); let owned = (value).to_string(); let result = owned.clone(); let _ = tasks.spawn_isolated(move || owned.len()); Box::new(move || result.len()) }
pub fn whole_alias(tasks: &Tasks) -> Box<dyn Fn() -> usize> { let text = String::from("x"); let value = text.as_str(); let alias = value; let owned = (alias).to_string(); let result = owned.clone(); let _ = tasks.spawn_isolated(move || owned.len()); Box::new(move || result.len()) }
pub fn whole_deferred(tasks: &Tasks) -> Box<dyn Fn() -> usize> { let text = String::from("x"); let value = text.as_str(); let alias; alias = value; let owned = (alias).to_string(); let result = owned.clone(); let _ = tasks.spawn_isolated(move || owned.len()); Box::new(move || result.len()) }
pub fn whole_reassigned(tasks: &Tasks) -> Box<dyn Fn() -> usize> { let text = String::from("x"); let value = text.as_str(); let mut alias = value; alias = value; let owned = (alias).to_string(); let result = owned.clone(); let _ = tasks.spawn_isolated(move || owned.len()); Box::new(move || result.len()) }
