pub fn borrow_reassigned(tasks: &Tasks) -> Box<dyn Fn() -> usize> { let text = String::from("x"); let value = text.as_str(); let mut alias = &value; alias = &value; let owned = (alias).to_string(); let result = owned.clone(); let _ = tasks.spawn_isolated(move || owned.len()); Box::new(move || result.len()) }
